//! The frozen, built-in repository state.
//!
//! CLI-free: no clap, no printing, no formatting decisions. It answers
//! questions about the repository and nothing else.

/// One commit of the frozen history.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Commit {
    pub hash: &'static str,
    pub author: &'static str,
    pub message: &'static str,
}

/// One branch of the frozen repository.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Branch {
    pub name: &'static str,
    pub hash: &'static str,
}

/// The history, newest first.
const COMMITS: [Commit; 3] = [
    Commit { hash: "a3f4", author: "alice", message: "Fix off-by-one" },
    Commit { hash: "b7e2", author: "bob", message: "Add parser" },
    Commit { hash: "c1a9", author: "alice", message: "Initial import" },
];

const BRANCHES: [Branch; 2] = [
    Branch { name: "main", hash: "a3f4" },
    Branch { name: "dev", hash: "b7e2" },
];

/// The branch HEAD is on.
const HEAD_BRANCH: &str = "main";

impl Branch {
    /// The full ref name, as `ref-list` sorts and prints it.
    pub fn ref_name(&self) -> String {
        format!("refs/heads/{}", self.name)
    }
}

/// The history newest first, capped at `limit` commits when one is given.
pub fn commits(limit: Option<u64>) -> Vec<Commit> {
    let take = match limit {
        Some(limit) => usize::try_from(limit).unwrap_or(usize::MAX),
        None => COMMITS.len(),
    };
    COMMITS.iter().take(take).copied().collect()
}

/// The commit with this hash, if the repository has one.
pub fn commit(hash: &str) -> Option<Commit> {
    COMMITS.iter().find(|commit| commit.hash == hash).copied()
}

/// The name of the current branch.
pub fn head_branch() -> &'static str {
    HEAD_BRANCH
}

/// The commit HEAD points at.
pub fn head_commit() -> Commit {
    let branch = branches()
        .into_iter()
        .find(|branch| branch.name == HEAD_BRANCH)
        .expect("the current branch exists in the frozen repository");
    commit(branch.hash).expect("the current branch points at a known commit")
}

/// Every branch, sorted by ref name.
pub fn branches() -> Vec<Branch> {
    let mut branches: Vec<Branch> = BRANCHES.to_vec();
    branches.sort_by_key(|branch| branch.ref_name());
    branches
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
