//! Configuration resolution.
//!
//! CLI-free: the file sources are resolved from an explicit working directory
//! and an explicit environment, so the whole precedence chain is testable
//! without touching the process.

use std::path::{Path, PathBuf};

/// The two configured keys, as they read from the file sources.
///
/// Command-line flags sit above this in the precedence chain and are applied
/// by the handler that owns the flag.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Config {
    pub log_limit: Option<u64>,
    pub user_name: Option<String>,
}

impl Config {
    /// The effective value of `key`, or `None` when the key has none.
    ///
    /// An unknown key never has an effective value.
    pub fn get(&self, key: &str) -> Option<String> {
        match key {
            "log.limit" => self.log_limit.map(|limit| limit.to_string()),
            "user.name" => self.user_name.clone(),
            _ => None,
        }
    }
}

/// The environment facts configuration resolution reads.
#[derive(Clone, Debug, Default)]
pub struct Environment {
    pub config_home: Option<PathBuf>,
    pub home: Option<PathBuf>,
}

impl Environment {
    /// Read the facts from the process environment.
    pub fn from_process() -> Self {
        Self {
            config_home: std::env::var_os("GITLIKE_CONFIG_HOME").map(PathBuf::from),
            home: std::env::var_os("HOME").map(PathBuf::from),
        }
    }

    /// The user configuration file, when the environment names one.
    fn user_config_path(&self) -> Option<PathBuf> {
        match &self.config_home {
            Some(dir) => Some(dir.join("config.toml")),
            None => self
                .home
                .as_ref()
                .map(|home| home.join(".config").join("gitlike").join("config.toml")),
        }
    }
}

/// The name of the per-directory configuration file.
const LOCAL_FILE: &str = ".gitlike.toml";

/// Resolve the effective file-sourced configuration.
///
/// Sources, highest precedence first: the nearest `.gitlike.toml` walking up
/// from `cwd`, then the user configuration file, then the built-in defaults.
/// Precedence is per key, so a local file that sets only one key leaves the
/// other to the user file.
pub fn load(cwd: &Path, env: &Environment) -> Config {
    let local = nearest_local_file(cwd).map(|path| read(&path)).unwrap_or_default();
    let user = env
        .user_config_path()
        .map(|path| read(&path))
        .unwrap_or_default();

    Config {
        log_limit: local.log_limit.or(user.log_limit),
        user_name: local.user_name.or(user.user_name),
    }
}

/// The nearest `.gitlike.toml`, walking up from `cwd` toward the root.
///
/// The first file found wins; files further up are not merged.
fn nearest_local_file(cwd: &Path) -> Option<PathBuf> {
    let mut dir = Some(cwd);
    while let Some(current) = dir {
        let candidate = current.join(LOCAL_FILE);
        if candidate.is_file() {
            return Some(candidate);
        }
        dir = current.parent();
    }
    None
}

/// Read one configuration file.
///
/// A file that cannot be read or parsed, and a value of the wrong shape,
/// contribute nothing. A file that exists still ends the upward walk.
fn read(path: &Path) -> Config {
    match std::fs::read_to_string(path) {
        Ok(text) => parse(&text),
        Err(_) => Config::default(),
    }
}

/// Parse one TOML document. Both `log.limit = 2` and the `[log]` table form
/// reach the same place, because a dotted key *is* a table in TOML.
fn parse(text: &str) -> Config {
    let Ok(document) = text.parse::<toml::Table>() else {
        return Config::default();
    };

    Config {
        log_limit: document
            .get("log")
            .and_then(|table| table.get("limit"))
            .and_then(toml::Value::as_integer)
            .filter(|limit| *limit > 0)
            .map(|limit| limit as u64),
        user_name: document
            .get("user")
            .and_then(|table| table.get("name"))
            .and_then(toml::Value::as_str)
            .map(str::to_owned),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn both_toml_spellings_reach_the_same_value() {
        assert_eq!(parse("log.limit = 2").log_limit, Some(2));
        assert_eq!(parse("[log]\nlimit = 2\n").log_limit, Some(2));
    }

    #[test]
    fn unset_keys_stay_unset() {
        let config = Config::default();
        assert_eq!(config.get("log.limit"), None);
        assert_eq!(config.get("user.name"), None);
    }

    #[test]
    fn an_unknown_key_has_no_effective_value() {
        let config = Config { log_limit: Some(2), user_name: Some("ada".into()) };
        assert_eq!(config.get("core.editor"), None);
        assert_eq!(config.get("log.limit").as_deref(), Some("2"));
        assert_eq!(config.get("user.name").as_deref(), Some("ada"));
    }

    #[test]
    fn malformed_or_ill_typed_values_contribute_nothing() {
        assert_eq!(parse("this is not toml").log_limit, None);
        assert_eq!(parse("log.limit = \"two\"").log_limit, None);
        assert_eq!(parse("log.limit = 0").log_limit, None);
        assert_eq!(parse("log.limit = -1").log_limit, None);
    }
}

