//! The plumbing byte contract.
//!
//! Plumbing output is not presentation: it is a stability contract for
//! scripts, so it is built here as bytes rather than in a template. Handlers
//! hand these bytes back as `Output::Binary`, which bypasses the render
//! pipeline entirely — no theme, no `--output` mode, no terminal detection,
//! and no pager can reach them.

use crate::repo::{Branch, Commit};

/// `gitlike ref-list`: one line per branch, sorted by ref name.
pub fn ref_list(branches: &[Branch]) -> Vec<u8> {
    let mut out = String::new();
    for branch in branches {
        out.push_str(&format!("{} {}\n", branch.hash, branch.ref_name()));
    }
    out.into_bytes()
}

/// `gitlike cat-object <hash>`: the object body of a known commit.
pub fn cat_object(commit: &Commit) -> Vec<u8> {
    format!("author {}\nmessage {}\n", commit.author, commit.message).into_bytes()
}

/// The stderr diagnostic for an unknown hash.
pub fn no_such_object(hash: &str) -> String {
    format!("gitlike: no such object: {hash}\n")
}

/// `gitlike config get <key>`: the effective value and a newline.
pub fn config_value(value: &str) -> Vec<u8> {
    format!("{value}\n").into_bytes()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::repo;

    #[test]
    fn ref_list_is_hash_then_ref_name() {
        assert_eq!(
            String::from_utf8(ref_list(&repo::branches())).unwrap(),
            "b7e2 refs/heads/dev\na3f4 refs/heads/main\n"
        );
    }

    #[test]
    fn cat_object_is_author_then_message() {
        let commit = repo::commit("b7e2").unwrap();
        assert_eq!(
            String::from_utf8(cat_object(&commit)).unwrap(),
            "author bob\nmessage Add parser\n"
        );
    }

    #[test]
    fn the_unknown_object_diagnostic_ends_in_a_newline() {
        assert_eq!(no_such_object("zzzz"), "gitlike: no such object: zzzz\n");
    }
}

