//! CLI adapters. Each one reads parsed arguments, calls the CLI-free core,
//! and returns view data (porcelain) or contract bytes (plumbing).

use standout::cli::{CommandContext, ExternalFailure, Output};
use standout::handler;

use crate::config::Config;
use crate::views::{CommitView, LogView, StatusView};
use crate::{plumbing, repo};

/// The exit status for `config get` on a key with no effective value.
const NO_EFFECTIVE_VALUE: u8 = 1;

/// The exit status for an unknown object hash.
const NO_SUCH_OBJECT: u8 = 3;

/// `gitlike log` — porcelain.
///
/// `--limit` is the highest-precedence source for `log.limit`; the file
/// sources are already resolved into the `Config` in app state.
#[handler]
pub fn log(
    #[arg] limit: Option<u64>,
    #[ctx] ctx: &CommandContext,
) -> Result<Output<LogView>, anyhow::Error> {
    let config = ctx.app_state.get_required::<Config>()?;
    let effective = limit.or(config.log_limit);

    Ok(Output::Render(LogView {
        commits: repo::commits(effective).into_iter().map(CommitView::from).collect(),
    }))
}

/// `gitlike status` — porcelain.
#[handler]
pub fn status(#[ctx] _ctx: &CommandContext) -> Result<Output<StatusView>, anyhow::Error> {
    Ok(Output::Render(StatusView {
        branch: repo::head_branch().to_owned(),
        head: repo::head_commit().into(),
    }))
}

/// `gitlike ref-list` — plumbing.
#[handler]
pub fn ref_list(#[ctx] _ctx: &CommandContext) -> Result<Output<()>, anyhow::Error> {
    Ok(Output::Binary {
        data: plumbing::ref_list(&repo::branches()),
        filename: "ref-list".to_owned(),
    })
}

/// `gitlike cat-object <hash>` — plumbing.
#[handler]
pub fn cat_object(
    #[arg] hash: String,
    #[ctx] _ctx: &CommandContext,
) -> Result<Output<()>, anyhow::Error> {
    let Some(commit) = repo::commit(&hash) else {
        // The status and the stderr bytes are this command's contract, so the
        // diagnostic is declared verbatim rather than framed as an app error.
        return Err(
            ExternalFailure::new(NO_SUCH_OBJECT, plumbing::no_such_object(&hash))?.into()
        );
    };

    Ok(Output::Binary {
        data: plumbing::cat_object(&commit),
        filename: "object".to_owned(),
    })
}

/// `gitlike config get <key>`.
#[handler]
pub fn config_get(
    #[arg] key: String,
    #[ctx] ctx: &CommandContext,
) -> Result<Output<()>, anyhow::Error> {
    let config = ctx.app_state.get_required::<Config>()?;

    let Some(value) = config.get(&key) else {
        // Nothing on either stream, status 1.
        return Err(ExternalFailure::new(NO_EFFECTIVE_VALUE, String::new())?.into());
    };

    Ok(Output::Binary {
        data: plumbing::config_value(&value),
        filename: "config-value".to_owned(),
    })
}

