//! Paging for porcelain output.
//!
//! Standout owns paging for `help --page` only, and hands a capture caller the
//! text with `SuccessKind::PagedHelp` instead of paging it — "only a printing
//! entry point may perform it". `gitlike` is that printing entry point, so the
//! policy lives here, next to the final write.

use std::io::Write;
use std::process::{Command, Stdio};

/// Whether this invocation may page, and through what.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Paging {
    Through(String),
    Off,
}

/// The environment facts the paging decision reads.
#[derive(Clone, Debug, Default)]
pub struct Environment {
    pub gitlike_pager: Option<String>,
    pub pager: Option<String>,
    pub stdout_is_terminal: bool,
    pub no_pager_flag: bool,
}

impl Environment {
    pub fn from_process(no_pager_flag: bool) -> Self {
        use std::io::IsTerminal;

        Self {
            gitlike_pager: std::env::var("GITLIKE_PAGER").ok(),
            pager: std::env::var("PAGER").ok(),
            stdout_is_terminal: std::io::stdout().is_terminal(),
            no_pager_flag,
        }
    }
}

/// Decide whether porcelain output is paged.
///
/// Piped stdout is never paged, `--no-pager` turns paging off for the
/// invocation, and with neither `GITLIKE_PAGER` nor `PAGER` set there is no
/// pager to use. `GITLIKE_PAGER` wins when it is set; a set-but-empty value
/// names no command, so it pages through nothing.
pub fn decide(env: &Environment) -> Paging {
    if env.no_pager_flag || !env.stdout_is_terminal {
        return Paging::Off;
    }

    let configured = env.gitlike_pager.as_ref().or(env.pager.as_ref());
    match configured {
        Some(command) if !command.trim().is_empty() => Paging::Through(command.clone()),
        _ => Paging::Off,
    }
}

/// Send `text` (plus its final newline) through the pager.
///
/// Returns `false` when the pager could not be started at all, so the caller
/// can fall back to stdout rather than lose the output. A pager that exits
/// early — `q` in `less` — is a normal end, not a failure.
pub fn page(command: &str, text: &str) -> bool {
    let Ok(mut child) = Command::new("sh")
        .arg("-c")
        .arg(command)
        .stdin(Stdio::piped())
        .spawn()
    else {
        return false;
    };

    if let Some(mut stdin) = child.stdin.take() {
        let _ = writeln!(stdin, "{text}");
        let _ = stdin.flush();
    }
    let _ = child.wait();
    true
}

#[cfg(test)]
mod tests {
    use super::*;

    fn terminal() -> Environment {
        Environment { stdout_is_terminal: true, ..Environment::default() }
    }

    #[test]
    fn a_pipe_is_never_paged() {
        let env = Environment {
            gitlike_pager: Some("less".into()),
            stdout_is_terminal: false,
            ..Environment::default()
        };
        assert_eq!(decide(&env), Paging::Off);
    }

    #[test]
    fn no_pager_turns_paging_off() {
        let env = Environment {
            pager: Some("less".into()),
            no_pager_flag: true,
            ..terminal()
        };
        assert_eq!(decide(&env), Paging::Off);
    }

    #[test]
    fn gitlike_pager_wins_over_pager() {
        let env = Environment {
            gitlike_pager: Some("more".into()),
            pager: Some("less".into()),
            ..terminal()
        };
        assert_eq!(decide(&env), Paging::Through("more".into()));
    }

    #[test]
    fn pager_is_the_fallback() {
        let env = Environment { pager: Some("less".into()), ..terminal() };
        assert_eq!(decide(&env), Paging::Through("less".into()));
    }

    #[test]
    fn neither_set_means_no_paging() {
        assert_eq!(decide(&terminal()), Paging::Off);
    }

    #[test]
    fn an_empty_pager_names_no_command() {
        let env = Environment { gitlike_pager: Some("  ".into()), ..terminal() };
        assert_eq!(decide(&env), Paging::Off);
    }
}

