//! Paging for porcelain output.
//!
//! Standout owns paging for `help --page` only, and hands a capture caller the
//! text with `SuccessKind::PagedHelp` instead of paging it — "only a printing
//! entry point may perform it". `gitlike` is that printing entry point, so the
//! policy lives here, next to the final write.

use std::io::Write;
use std::process::{Command, Stdio};

/// Whether this invocation may page, and through what.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Paging {
    Through(String),
    Off,
}

/// The environment facts the paging decision reads.
#[derive(Clone, Debug, Default)]
pub struct Environment {
    pub gitlike_pager: Option<String>,
    pub pager: Option<String>,
    pub stdout_is_terminal: bool,
    pub no_pager_flag: bool,
}

impl Environment {
