    let expected = "b7e2 refs/heads/dev\na3f4 refs/heads/main\n";

    for mode in ["auto", "term", "text", "term-debug", "json", "yaml", "xml", "csv"] {
        let out = Run::new().args(&["ref-list", "--output", mode]);
        assert_eq!(stdout(&out), expected, "--output {mode} moved the bytes");
        assert_eq!(code(&out), 0);
    }

    for run in [
        Run::new().env("GITLIKE_THEME", "mono"),
        Run::new().env("GITLIKE_THEME", "default"),
        Run::new().env("NO_COLOR", "1"),
        Run::new().env("PAGER", "sed s/^/PAGED:/"),
    ] {
        assert_eq!(stdout(&run.args(&["ref-list"])), expected);
    }
}

#[test]
fn porcelain_is_plain_when_piped_and_styled_on_request() {
    let run = Run::new();

    // Not a terminal: no ANSI.
    assert!(!stdout(&run.args(&["log"])).contains('\u{1b}'));
    // Asked for it: ANSI.
    assert!(stdout(&run.args(&["log", "--output", "term"])).contains('\u{1b}'));
}

#[test]
fn the_mono_theme_and_no_color_leave_porcelain_unstyled() {
    for run in [
        Run::new().env("GITLIKE_THEME", "mono"),
        Run::new().env("NO_COLOR", "1"),
        Run::new().env("NO_COLOR", ""),
    ] {
        let out = run.args(&["log", "--output", "term"]);
        assert_eq!(stdout(&out), FULL_LOG);
    }
}

#[test]
fn an_unknown_theme_falls_back_to_the_default_one() {
    let run = Run::new().env("GITLIKE_THEME", "chartreuse");
    let out = run.args(&["log", "--output", "term"]);

    assert_eq!(code(&out), 0);
    assert!(stdout(&out).contains('\u{1b}'));
}

#[test]
fn config_get_reports_an_unset_key_with_status_one_and_no_output() {
    let run = Run::new();
    let out = run.args(&["config", "get", "user.name"]);

    assert_eq!(code(&out), 1);
    assert_eq!(stdout(&out), "");
    assert_eq!(stderr(&out), "");
}

#[test]
fn config_get_walks_up_to_the_nearest_file() {
    let root = PathBuf::from(env!("CARGO_TARGET_TMPDIR")).join("walk");
    let near = root.join("near");
    let deep = near.join("deep");
    std::fs::create_dir_all(&deep).unwrap();
    std::fs::write(root.join(".gitlike.toml"), "log.limit = 3\nuser.name = \"far\"\n").unwrap();
    std::fs::write(near.join(".gitlike.toml"), "[log]\nlimit = 1\n").unwrap();

    let run = Run::new().cwd(&deep);

    // The nearest file wins outright: the one further up is not merged.
    assert_eq!(stdout(&run.args(&["config", "get", "log.limit"])), "1\n");
    assert_eq!(code(&run.args(&["config", "get", "user.name"])), 1);
    assert_eq!(stdout(&run.args(&["log"])), "a3f4 Fix off-by-one (alice)\n");
    // A command-line flag still outranks it.
    assert_eq!(stdout(&run.args(&["log", "--limit", "2"])).lines().count(), 2);
}

#[test]
fn the_user_config_file_is_the_next_source_down() {
    let home = PathBuf::from(env!("CARGO_TARGET_TMPDIR")).join("xdg");
    std::fs::create_dir_all(&home).unwrap();
    std::fs::write(home.join("config.toml"), "log.limit = 2\nuser.name = \"ada\"\n").unwrap();

    let run = Run::new().env("GITLIKE_CONFIG_HOME", &home.display().to_string());

    assert_eq!(stdout(&run.args(&["config", "get", "user.name"])), "ada\n");
    assert_eq!(stdout(&run.args(&["config", "get", "log.limit"])), "2\n");
    assert_eq!(stdout(&run.args(&["log"])).lines().count(), 2);
}

#[test]
fn config_get_on_an_unknown_key_has_no_effective_value() {
    let run = Run::new();
    let out = run.args(&["config", "get", "core.editor"]);

    assert_eq!(code(&out), 1);
    assert_eq!(stdout(&out), "");
}

#[test]
fn usage_errors_are_status_two() {
    let run = Run::new();

    for args in [
        vec!["bogus"],                 // unknown command
        vec!["log", "--bogus"],        // unknown flag
        vec!["log", "--limit", "0"],   // bad flag value
        vec!["log", "--limit", "two"], // bad flag value
        vec![],                        // no command at all
    ] {
        let out = run.args(&args);
        assert_eq!(code(&out), 2, "{args:?} should be a usage error");
        assert_eq!(stdout(&out), "", "{args:?} should say nothing on stdout");
    }
}

#[test]
fn a_pipe_is_never_paged() {
    let run = Run::new().env("PAGER", "sed s/^/PAGED:/");

    // Output is captured through a pipe, so paging is off whatever PAGER says.
    assert_eq!(stdout(&run.args(&["log"])), FULL_LOG);
    assert!(!stdout(&run.args(&["log"])).contains("PAGED:"));
}

#[test]
fn no_pager_is_accepted_in_both_positions() {
    let run = Run::new();

    assert_eq!(code(&run.args(&["--no-pager", "log"])), 0);
    assert_eq!(stdout(&run.args(&["log", "--no-pager"])), FULL_LOG);
}

