//! `gitlike` — a tiny version-control inspector.
//!
//! Porcelain (`log`, `status`) renders through standout's template and theme
//! pipeline. Plumbing (`ref-list`, `cat-object`) and `config get` return
//! `Output::Binary`, which bypasses rendering, so their bytes are the same
//! under every theme, `--output` mode and terminal.
//!
//! The final write lives here rather than in `App::run`, because paging is a
//! terminal side effect only a printing entry point may perform.

mod config;
mod handlers;
mod pager;
mod plumbing;
mod repo;
mod views;

use std::io::Write;
use std::path::PathBuf;

use clap::{CommandFactory, Parser, Subcommand};
use standout::cli::{
    App, CompletedRun, Dispatch, DispatchResult, RunErrorKind, SuccessKind,
};
use standout::{embed_styles, embed_templates, InputSources, TargetProperties};

use crate::pager::Paging;

/// Usage errors: unknown command, unknown flag, bad flag value.
const USAGE_ERROR: i32 = 2;

/// Any other framework-reported failure.
const RUNTIME_ERROR: i32 = 1;

#[derive(Parser)]
#[command(name = "gitlike", about = "Inspect a small, frozen repository")]
struct Cli {
    /// Do not page output for this invocation
    #[arg(long, global = true)]
    no_pager: bool,

    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Dispatch)]
#[dispatch(handlers = handlers)]
enum Commands {
    /// Show the commit history, newest first
    #[dispatch(pure)]
    Log {
        /// Show at most this many commits
        #[arg(long, value_name = "N", value_parser = clap::value_parser!(u64).range(1..))]
        limit: Option<u64>,
    },

    /// Show the current branch and what HEAD points at
    #[dispatch(pure)]
    Status,

    /// List every branch ref, sorted by ref name
    #[dispatch(pure, binary)]
    RefList,

    /// Print the body of one object
    #[dispatch(pure, binary)]
    CatObject {
        /// The object hash
        hash: String,
    },

    /// Inspect configuration
    #[dispatch(nested)]
    #[command(subcommand)]
    Config(ConfigCommands),
}

#[derive(Subcommand, Dispatch)]
#[dispatch(handlers = handlers::config)]
enum ConfigCommands {
    /// Print the effective value of a configuration key
    #[dispatch(pure, binary)]
    Get {
        /// The configuration key, such as `log.limit`
        key: String,
    },
}

fn main() {
    let args: Vec<std::ffi::OsString> = std::env::args_os().collect();
    let no_pager_flag = args.iter().any(|arg| arg == "--no-pager");

    // `NO_COLOR` set to anything, and the `mono` theme, both mean unstyled
    // porcelain. Selecting the unstyled theme covers every output mode, since
    // an explicit `--output term` resolves tags regardless of the destination.
    let styling = Styling::from_process();

    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let config = config::load(&cwd, &config::Environment::from_process());

    let app = match build_app(styling.theme, config) {
        Ok(app) => app,
        Err(error) => {
            eprintln!("gitlike: {error}");
            std::process::exit(RUNTIME_ERROR);
        }
    };

    let mut target = TargetProperties::detect();
    if styling.suppress_color {
        target.stdout_color_capability = false;
        target.stderr_color_capability = false;
    }

    let result = app.run_with(Cli::command(), args, target, InputSources::from_process());
    let paging = pager::decide(&pager::Environment::from_process(no_pager_flag));

    std::process::exit(emit(result, &paging));
}

/// Which theme this invocation renders with, and whether color is suppressed.
struct Styling {
    theme: &'static str,
    suppress_color: bool,
}

impl Styling {
    fn from_process() -> Self {
        let no_color = std::env::var_os("NO_COLOR").is_some();
        let mono = no_color
            || std::env::var("GITLIKE_THEME").map(|name| name == "mono").unwrap_or(false);

        Self {
            theme: if mono { "mono" } else { "default" },
            suppress_color: no_color,
        }
    }
}

fn build_app(theme: &str, config: config::Config) -> Result<App, Box<dyn std::error::Error>> {
    Ok(App::builder()
        .version(env!("CARGO_PKG_VERSION"))
        .app_state(config)
        .templates(embed_templates!("src/templates"))
        .styles(embed_styles!("src/styles"))
        .default_theme(theme)
        .commands(Commands::dispatch_config())?
        .build()?)
}

/// Perform the final write and report the process exit status.
fn emit(result: CompletedRun, paging: &Paging) -> i32 {
    let success = result.success_kind();

    match result.into_outcome() {
        // Porcelain: rendered text, paged when this invocation pages.
        DispatchResult::Handled(output) => {
            let command_output = matches!(success, Some(SuccessKind::Command));
            let pageable = command_output || matches!(success, Some(SuccessKind::PagedHelp));

            // A rendered page has already had its final newline consumed, and
            // the process edge appends exactly one. Clap's own help and
            // version displays carry theirs, so they are not given a second.
            let text = if command_output {
                output.as_str()
            } else {
                output.as_str().strip_suffix('\n').unwrap_or(output.as_str())
            };

            if let (true, Paging::Through(command)) = (pageable, paging) {
                if pager::page(command, text) {
                    return 0;
                }
            }
            write_line(text)
        }

        // Plumbing: bytes exactly as the handler built them, never paged.
        DispatchResult::Binary(bytes, _filename) => write_bytes(&bytes),

        DispatchResult::Silent => 0,

        DispatchResult::Error(error) => match error.kind() {
            // An application-declared status and a verbatim diagnostic.
            RunErrorKind::External => {
                let mut stderr = std::io::stderr();
                let _ = stderr.write_all(error.as_str().as_bytes());
                let _ = stderr.flush();
                i32::from(error.exit_status().code())
            }
            RunErrorKind::ClapUsage => {
                write_diagnostic(error.as_str());
                USAGE_ERROR
            }
            _ => {
                write_diagnostic(error.as_str());
                RUNTIME_ERROR
            }
        },

        // No handler claimed the command; nothing else owns it here.
        DispatchResult::NoMatch(_) => USAGE_ERROR,

        _ => 0,
    }
}

/// Write rendered text plus the one newline the process edge appends.
///
/// A closed downstream pipe means the consumer stopped reading early, which
/// is a success, not a write failure.
fn write_line(text: &str) -> i32 {
    let mut stdout = std::io::stdout();
    match writeln!(stdout, "{text}").and_then(|()| stdout.flush()) {
        Ok(()) => 0,
        Err(error) if error.kind() == std::io::ErrorKind::BrokenPipe => 0,
        Err(error) => {
            eprintln!("gitlike: {error}");
            RUNTIME_ERROR
        }
    }
}

/// Write a framework diagnostic to stderr, on one line of its own.
fn write_diagnostic(text: &str) {
    eprintln!("{}", text.strip_suffix('\n').unwrap_or(text));
}

/// Write contract bytes with nothing added.
fn write_bytes(bytes: &[u8]) -> i32 {
    let mut stdout = std::io::stdout();
    match stdout.write_all(bytes).and_then(|()| stdout.flush()) {
        Ok(()) => 0,
        Err(error) if error.kind() == std::io::ErrorKind::BrokenPipe => 0,
        Err(error) => {
            eprintln!("gitlike: {error}");
            RUNTIME_ERROR
        }
    }
}

